63	/**
64	 * @brief 开机 splash 页状态。
65	 */
66	typedef struct {
67	    lv_obj_t * root;           /**< lv_pm 页面根。 */
68	    lv_obj_t * cont;           /**< 淡出目标（与 root 相同）。 */
69	    helm_splash_t splash;      /**< 共用 logo / 事项行 / 进度条。 */
70	    lv_timer_t * poll_timer;   /**< 50 ms 启动事项状态机。 */
71	    uint32_t appear_tick;      /**< will_appear 时刻，用于总超时。 */
72	    uint32_t ready_tick;       /**< 末项滚出后的短 hold。 */
73	    uint32_t chore_t0;         /**< 当前 step 起始。 */
74	    int16_t bg_applied;        /**< 已应用的背景灰阶；-1 未设。 */
75	    uint8_t bar_goal;          /**< 进度条目标，避免重复开动画。 */
76	    uint8_t chore;             /**< `STARTUP_CHORE_*`。 */
77	    uint8_t step;              /**< `STARTUP_STEP_*`。 */
78	    char chore_key[16];        /**< 当前事项左侧文案。 */
79	    bool exiting;              /**< 已开始 fade/pop。 */
80	    bool map_opened;           /**< 已 `boot_begin_load`。 */
81	    bool bg_started;           /**< 黑→白结束，chrome 已露出。 */
82	    bool sound_wait;           /**< 黑屏等开机提示音播完。 */
83	} startup_page_t;
