165	/** @brief splash 的**最终**底色灰阶（跟主题）。
166	 *  @details 用户 2026-09-26 晚："开关机界面也[要]受主题变化影响" ⇒ 日光是原来的
167	 *           白底黑字（255），夜间走黑底白字（0）。`helm_splash_set_gray()` 的约定：
168	 *           传进去的是**背景**灰阶，文字/进度条自动取反（`ink = 255 - g`）。
169	 *           logo 是固定位图（平均亮度 146，黑底上也看得见），不跟着换。 */
170	static uint8_t startup_theme_gray(void)
171	{
172	    return helm_pal_night() ? 0u : 255u;
173	}
