175	static void startup_bg_exec(void * var, int32_t v)
176	{
177	    startup_page_t * ui = (startup_page_t *)var;
178	    uint8_t step;
179	    uint8_t g;
180	
181	    if (!ui || ui->exiting) {
182	        return;
183	    }
184	
185	    if (v < 0) {
186	        v = 0;
187	    }
188	    if (v > STARTUP_BG_STEPS) {
189	        v = STARTUP_BG_STEPS;
190	    }
191	    step = (uint8_t)v;
192	    /* 渐亮的**目标**跟主题：夜间目标是黑 ⇒ 这段动画等于不动（也就不会闪一下白）。 */
193	    g = (uint8_t)((step * (uint32_t)startup_theme_gray()) / STARTUP_BG_STEPS);
194	    startup_apply_bg(ui, g);
195	}
