197	static void startup_bg_ready(lv_anim_t * a)
198	{
199	    startup_page_t * ui = a ? (startup_page_t *)a->var : NULL;
200	
201	    if (!ui || ui->exiting) {
202	        return;
203	    }
204	
205	    startup_apply_bg(ui, startup_theme_gray());
206	    ui->bg_started = true;
207	    ui->appear_tick = lv_tick_get();
208	    helm_splash_set_chrome_hidden(&ui->splash, false);
209	    helm_splash_bar_set(&ui->splash, 0);
210	    startup_arm_chore(ui, STARTUP_CHORE_SALVAGE);
211	    startup_start_poll(ui);
212	}
