214	/** @brief 换主题后重铺 splash 底色（跟主题那件事的"变化"那一半）。
215	 *  @details 开机时主题是**先 KV 读回、后渐变**，但渐变可能在读回之前就结束
216	 *           （`startup_bg_ready` 先跑）⇒ 得有个"主题变了再铺一次"的入口。
217	 *           由 `helm_theme_poll_apply()` 在循环顶调用（安全点，同 ①②③）。 */
218	void startup_page_theme_refresh(void)
219	{
220	    startup_page_t * ui = s_startup;
221	
222	    if (!ui || !ui->root || ui->exiting || !ui->bg_started) {
223	        return;                    /* 没在放 splash / 渐变还没走完：结束后自己会取新值 */
224	    }
225	
226	    startup_apply_bg(ui, startup_theme_gray());
227	}
