309	static void startup_arm_chore(startup_page_t * ui, unsigned chore)
310	{
311	    static const char *const keys[STARTUP_CHORE_COUNT] = {
312	        "骑行记录", "系统字体", "地图加载"
313	    };
314	    static const char *const busy[STARTUP_CHORE_COUNT] = {
315	        "恢复中", "加载中", "加载中"
316	    };
317	
318	    if (ui == NULL || chore >= STARTUP_CHORE_COUNT) {
319	        return;
320	    }
321	
322	    ui->chore = (uint8_t)chore;
323	    ui->step = STARTUP_STEP_SLIDE_IN;
324	    ui->chore_t0 = lv_tick_get();
325	    lv_snprintf(ui->chore_key, sizeof(ui->chore_key), "%s", keys[chore]);
326	    startup_bar_goal(ui, startup_chore_bar(chore));
327	    startup_row(ui, busy[chore], true);
328	    helm_splash_slide_in(&ui->splash);
329	}
