347	/**
348	 * @brief 推进当前事项；完成则写结果行并返回 true。
349	 * @return 本项已出结果为 true，还需再泵为 false。
350	 */
351	static bool startup_chore_pump(startup_page_t * ui)
352	{
353	    if (ui == NULL) {
354	        return true;
355	    }
356	
357	    switch (ui->chore) {
358	    case STARTUP_CHORE_SALVAGE:
359	        if (!bicycle_ride_gpx_salvage_boot_pump()) {
360	            return false;
361	        }
362	
363	        startup_row(ui, startup_salvage_result(), false);
364	        return true;
365	
366	    case STARTUP_CHORE_FONT:
367	#ifdef CONFIG_MYVENDOR_FACTORY_MODE
368	        startup_row(ui, "已跳过", false);
369	        return true;
370	#else
371	        {
372	            int n;
373	
374	            for (n = 0; n < STARTUP_FONT_CHUNKS; n++) {
375	                if (myvendor_system_font_preload_pump()) {
376	                    (void)myvendor_system_font_lv_bind();
377	                    startup_use_sys_status_font(ui);
378	                    startup_row(ui,
379	                                myvendor_system_font_preloaded() ? "已加载" :
380	                                "未找到",
381	                                false);
382	                    LV_LOG_INFO("startup: font ready, loading map");
383	                    return true;
384	                }
385	
386	                myvendor_watchdog_busy_pump();
387	            }
388	        }
389	        return false;
390	#endif
391	
392	    case STARTUP_CHORE_MAP:
393	        if (!ui->map_opened) {
394	            if (!map_page_boot_begin_load()) {
395	                LV_LOG_ERROR("startup: map boot load failed");
396	                startup_row(ui, "失败", false);
397	                return true;
398	            }
399	
400	            ui->map_opened = true;
401	            startup_bar_goal(ui, 85);
402	            startup_row(ui, "文件中", true);
403	            return false;
404	        }
405	
406	        if (!map_page_boot_prepare(live_map_page_instance())) {
407	            return false;
408	        }
409	
410	        startup_bar_goal(ui, 100);
411	        startup_row(ui, "已加载", false);
412	        LV_LOG_INFO("startup: files ready, map render deferred");
413	        return true;
414	
415	    default:
416	        return true;
417	    }
418	}
