471	static void startup_poll_cb(lv_timer_t * tmr)
472	{
473	    startup_page_t * ui = (startup_page_t *)lv_timer_get_user_data(tmr);
474	    uint32_t elapsed;
475	    unsigned next;
476	
477	    if (!ui || ui->exiting) {
478	        return;
479	    }
480	
481	    helm_splash_pump(&ui->splash);
482	
483	    elapsed = lv_tick_elaps(ui->appear_tick);
484	
485	    /* Host already on USB: skip map file preparation (same LittleFS as MTP). */
486	    {
487	        myvendor_mtp_status_t mtp_st;
488	
489	        memset(&mtp_st, 0, sizeof(mtp_st));
490	        (void)myvendor_mtp_get_status(&mtp_st);
491	        if (mtp_st.plug >= MYVENDOR_MTP_PLUG_ENUM) {
492	            startup_begin_exit(ui);
493	            return;
494	        }
495	    }
496	
497	    /* 黑屏：开机音播完再黑→白。白屏后才跑 GPX/字体/地图。 */
498	    if (!ui->bg_started) {
499	        if (ui->sound_wait) {
500	            if (!myvendor_sound_idle()) {
501	                return;
502	            }
503	
504	            ui->sound_wait = false;
505	            startup_start_bg_anim(ui);
506	        }
507	
508	        return;
509	    }
510	
511	    /* 白屏还在恢复 GPX 时不要因总超时直接进主界面。
512	     * 地图事项若被 GNSS/LFS 拖住：12 s 后进主界面，文件留给 LiveMap。 */
513	    if (elapsed >= STARTUP_MAX_WAIT_MS &&
514	        ui->chore != STARTUP_CHORE_SALVAGE) {
515	        if (ui->chore == STARTUP_CHORE_MAP) {
516	            LV_LOG_WARN("startup: map timeout, enter live map");
517	            startup_bar_goal(ui, 100);
518	            startup_row(ui, "已加载", false);
519	            startup_begin_exit(ui);
520	            return;
521	        }
522	
523	        LV_LOG_WARN("startup: timeout, skip to map");
524	#ifndef CONFIG_MYVENDOR_FACTORY_MODE
525	        (void)myvendor_system_font_lv_bind();
526	        startup_use_sys_status_font(ui);
527	#endif
528	        if (!ui->map_opened) {
529	            (void)map_page_boot_begin_load();
530	            ui->map_opened = true;
531	        }
532	
533	        lv_snprintf(ui->chore_key, sizeof(ui->chore_key), "%s", "地图加载");
534	        ui->chore = STARTUP_CHORE_MAP;
535	        ui->step = STARTUP_STEP_RUN;
536	        ui->chore_t0 = lv_tick_get();
537	        startup_bar_goal(ui, 62);
538	        startup_row(ui, "加载中", true);
539	        return;
540	    }
541	
542	    switch (ui->step) {
543	    case STARTUP_STEP_SLIDE_IN:
544	        if (lv_tick_elaps(ui->chore_t0) < STARTUP_SLIDE_MS) {
545	            return;
546	        }
547	
548	        ui->step = STARTUP_STEP_RUN;
549	        return;
550	
551	    case STARTUP_STEP_RUN:
552	        if (!startup_chore_pump(ui)) {
553	            return;
554	        }
555	
556	        ui->step = STARTUP_STEP_HOLD;
557	        ui->chore_t0 = lv_tick_get();
558	        return;
559	
560	    case STARTUP_STEP_HOLD:
561	        if (lv_tick_elaps(ui->chore_t0) < STARTUP_HOLD_MS) {
562	            return;
563	        }
564	
565	        ui->step = STARTUP_STEP_SLIDE_OUT;
566	        ui->chore_t0 = lv_tick_get();
567	        helm_splash_slide_out(&ui->splash);
568	        return;
569	
570	    case STARTUP_STEP_SLIDE_OUT:
571	        if (lv_tick_elaps(ui->chore_t0) < STARTUP_SLIDE_MS) {
572	            return;
573	        }
574	
575	        next = startup_chore_next(ui->chore);
576	        if (next < STARTUP_CHORE_COUNT) {
577	            startup_arm_chore(ui, next);
578	            return;
579	        }
580	
581	        if (ui->ready_tick == 0u) {
582	            ui->ready_tick = lv_tick_get();
583	        }
584	
585	        if (lv_tick_elaps(ui->ready_tick) < STARTUP_READY_HOLD_MS) {
586	            return;
587	        }
588	
589	        startup_begin_exit(ui);
590	        return;
591	
592	    default:
593	        return;
594	    }
