73	/** @brief 事项行位移 + 透明度动画。out 结束后吃 pending。 */
74	static void helm_splash_slide_anim(helm_splash_t *s, int32_t y0, int32_t y1,
75	                                  int32_t o0, int32_t o1, bool out)
76	{
77	    lv_anim_t a;
78	    uint32_t ms;
79	
80	    if (s == NULL || s->lab == NULL) {
81	        return;
82	    }
83	
84	    ms = s->slide_ms == 0u ? HELM_SPLASH_SLIDE_MS : s->slide_ms;
85	    lv_anim_delete(s->lab, helm_splash_ty);
86	    lv_anim_delete(s->lab, helm_splash_fade);
87	
88	    lv_obj_set_style_translate_y(s->lab, (lv_coord_t)y0, 0);
89	    helm_splash_lab_opa(s, (lv_opa_t)o0);
90	
91	    lv_anim_init(&a);
92	    lv_anim_set_var(&a, s->lab);
93	    lv_anim_set_values(&a, y0, y1);
94	    lv_anim_set_time(&a, ms);
95	    lv_anim_set_path_cb(&a, lv_anim_path_ease_in_out);
96	    lv_anim_set_exec_cb(&a, helm_splash_ty);
97	    if (out) {
98	        lv_anim_set_ready_cb(&a, helm_splash_out_ready);
99	    }
100	
101	    lv_anim_start(&a);
102	
103	    lv_anim_init(&a);
104	    lv_anim_set_var(&a, s->lab);
105	    lv_anim_set_values(&a, o0, o1);
106	    lv_anim_set_time(&a, ms);
107	    lv_anim_set_path_cb(&a, lv_anim_path_ease_in_out);
108	    lv_anim_set_exec_cb(&a, helm_splash_fade);
109	    lv_anim_start(&a);
110	}
