226	    lv_obj_set_style_bg_color(s->root, lv_color_make(g, g, g), 0);
227	    lv_obj_set_style_bg_opa(s->root, LV_OPA_COVER, 0);
228	
229	    if (s->clip != NULL) {
230	        lv_obj_set_style_bg_color(s->clip, lv_color_make(g, g, g), 0);
231	        lv_obj_set_style_bg_opa(s->clip, LV_OPA_COVER, 0);
232	    }
233	
234	    if (s->name != NULL) {
235	        lv_obj_set_style_text_color(s->name, lv_color_make(ink, ink, ink), 0);
236	    }
237	
238	    if (s->lab != NULL) {
239	        lv_obj_set_style_text_color(s->lab, lv_color_make(ink, ink, ink), 0);
240	    }
241	
242	    if (s->bar != NULL) {
243	        lv_obj_set_style_bg_color(s->bar, lv_color_make(track, track, track), 0);
244	    }
245	
246	    if (s->bar_fill != NULL) {
247	        lv_obj_set_style_bg_color(s->bar_fill, lv_color_make(ink, ink, ink), 0);
248	    }
